#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int d) : data(d), next(nullptr) {}
};

void insertSorted(Node*& head, int value) {
    Node* newNode = new Node(value);
    if (head == nullptr || value < head->data) {
        newNode->next = head;
        head = newNode;
        return;
    }
    Node* prev = head;
    while (prev->next != nullptr && prev->next->data < value) {
        prev = prev->next;
    }
    newNode->next = prev->next;
    prev->next = newNode;
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->next;
    }
    cout << endl;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = nullptr;
    insertSorted(head, 10);
    insertSorted(head, 30);
    insertSorted(head, 40);
    insertSorted(head, 20);
    printList(head);
    freeList(head);
    return 0;
}
